-- Ente Palazhi - initial schema (SQLite).
--
-- Access rule that the database does NOT enforce for us: the public site
-- may only read rows where is_published = 1 and archived_at is null. Every
-- query in lib/data/projects.ts carries that filter explicitly; anything
-- that reads without it belongs in lib/data/admin.ts behind requireAdmin().
--
-- Storage conventions (lib/db.ts relies on them):
-- - ids: lowercase UUID v4 text, generated by the column default
-- - timestamps: ISO-8601 UTC text, e.g. 2026-11-21T05:37:24.123Z
-- - calendar dates: YYYY-MM-DD text
-- - booleans: 0/1 in columns declared `boolean`
-- Foreign keys are enforced because lib/db.ts turns on PRAGMA foreign_keys.

create table projects (
  id                      text not null primary key default (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6)))),
  slug                    text not null unique,

  name_en                 text not null,
  name_ml                 text null,
  description_en          text null,
  description_ml          text null,

  -- One of the slugs in lib/areas.ts. Validated in lib/schemas.ts rather
  -- than by a CHECK here, so the area list can change without a migration.
  area                    text not null,
  local_body              text null,
  local_body_type         text null
                            check (local_body_type in ('panchayat', 'municipality', 'corporation', 'other')),
  latitude                real null,
  longitude               real null,

  cost_inr                real null check (cost_inr is null or cost_inr >= 0),
  cost_note               text null check (cost_note in ('sanctioned', 'revised_estimate')),
  tenure                  text null,
  inaugurated_on          text null,
  promised_completion_on  text null,
  department              text null,

  status                  text not null default 'lead'
                            check (status in ('lead', 'reported', 'acknowledged', 'work_resumed', 'completed', 'no_action')),
  source                  text not null check (source in ('admin', 'public')),

  -- submitted_on is always set; reported_on is null until the issue has
  -- been verified and documented. The day counter runs from
  -- coalesce(reported_on, submitted_on) - see lib/dates.ts. Default is
  -- today's calendar date in India (UTC+5:30, no daylight saving).
  submitted_on            text not null default (date('now', '+330 minutes')),
  reported_on             text null,
  resolved_on             text null,

  instagram_url           text null,
  youtube_url             text null,

  is_published            boolean not null default 0,
  archived_at             text null,
  updated_by              text null,

  created_at              text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at              text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),

  check (resolved_on is null or resolved_on >= coalesce(reported_on, submitted_on))
);

create index ix_projects_published on projects (is_published, archived_at);
create index ix_projects_area on projects (area);
create index ix_projects_status on projects (status);
create index ix_projects_submitted_on on projects (submitted_on desc);

-- The status timeline. Append-only in spirit: entries are added, the
-- record is not rewritten.
create table project_updates (
  id            text not null primary key default (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6)))),
  project_id    text not null references projects (id) on delete cascade,
  happened_on   text not null,
  title_en      text not null,
  title_ml      text null,
  body_en       text null,
  body_ml       text null,
  status_after  text null
                  check (status_after in ('lead', 'reported', 'acknowledged', 'work_resumed', 'completed', 'no_action')),
  source_url    text null,
  created_at    text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

create index ix_project_updates_project on project_updates (project_id, happened_on desc);

-- Approved photos. storage_path is relative to UPLOAD_DIR/public and is
-- served at /media/<storage_path> (see lib/storage.ts).
create table project_media (
  id            text not null primary key default (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6)))),
  project_id    text not null references projects (id) on delete cascade,
  storage_path  text not null,
  caption_en    text null,
  caption_ml    text null,
  sort_order    integer not null default 0,
  created_at    text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

create index ix_project_media_project on project_media (project_id, sort_order);

-- Contact details of whoever sent a report. Admin-only: never selected by
-- anything in lib/data/projects.ts.
create table project_submitters (
  id                   text not null primary key default (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6)))),
  project_id           text not null references projects (id) on delete cascade,
  name                 text null,
  email                text null,
  phone                text null,
  note                 text null,
  ip_hash              text null,
  -- JSON array of paths under UPLOAD_DIR/pending, uploaded with the report
  -- and not yet approved. Approval moves the files into UPLOAD_DIR/public
  -- and creates the project_media rows.
  pending_photo_paths  text not null default '[]',
  created_at           text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

create index ix_project_submitters_project on project_submitters (project_id);

create table admin_audit_log (
  id           text not null primary key default (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6)))),
  actor_email  text not null,
  action       text not null,
  project_id   text null references projects (id) on delete set null,
  -- JSON object.
  diff         text null,
  created_at   text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

create index ix_admin_audit_log_project on admin_audit_log (project_id);
create index ix_admin_audit_log_created on admin_audit_log (created_at desc);

-- Per-day counters: "submit:<ip hash>" for the public report form,
-- "upload:<ip hash>" for photo uploads, "login:<ip hash>" for failed admin
-- sign-ins. See lib/ratelimit.ts.
create table rate_limit (
  bucket  text not null,
  day_on  text not null,
  hits    integer not null default 0,
  primary key (bucket, day_on)
);

-- Single-row settings, editable from /admin/settings with no redeploy.
create table site_settings (
  id                     integer not null primary key default 1 check (id = 1),

  support_enabled        boolean not null default 0,
  support_title_en       text null,
  support_title_ml       text null,
  support_body_en        text null,
  support_body_ml        text null,
  support_email          text null,
  support_phone          text null,
  support_upi_id         text null,
  support_link_url       text null,
  support_link_label_en  text null,
  support_link_label_ml  text null,

  instagram_url          text null,

  updated_at             text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_by             text null
);

insert into site_settings (id) values (1);

-- Admin accounts. Created with scripts/create-admin.mjs; there is no
-- self-service sign-up.
create table admin_users (
  id             text not null primary key default (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6)))),
  email          text not null unique,
  -- scrypt$<salt hex>$<hash hex> - see lib/password.ts.
  password_hash  text not null,
  created_at     text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- Only the SHA-256 of the session token is stored, so a leaked copy of
-- this table cannot be replayed as a cookie.
create table admin_sessions (
  token_hash  text not null primary key,
  user_id     text not null references admin_users (id) on delete cascade,
  expires_at  text not null,
  created_at  text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
